// Verus specifications for the Fibonacci function
#[verifier::spec]
fn fibonacci(n: usize) -> Vec<i32> {
    // Precondition: n must be at least 2 to compute Fibonacci numbers
    // Ensures: The returned vector contains the first n Fibonacci numbers
    // Requires: n >= 2
    // Ensures: fib_sequence.len() == n
    // Ensures: fib_sequence[0] == 0
    // Ensures: fib_sequence[1] == 1
    // Ensures: forall(i: usize, 2 <= i < n => fib_sequence[i] == fib_sequence[i - 1] + fib_sequence[i - 2])
    // Decreases: n
    assert(n >= 2); // Ensure n is at least 2

    let mut fib_sequence = vec![0; n]; // Create a vector of size n initialized with 0
    fib_sequence[0] = 0; // F(0)
    fib_sequence[1] = 1; // F(1)

    // Loop invariant: 
    // 1. 2 <= i <= n
    // 2. fib_sequence[0] == 0
    // 3. fib_sequence[1] == 1
    // 4. forall(j: usize, 2 <= j < i => fib_sequence[j] == fib_sequence[j - 1] + fib_sequence[j - 2])
    for i in 2..n {
        fib_sequence[i] = fib_sequence[i - 1] + fib_sequence[i - 2]; // F(i) = F(i-1) + F(i-2)
    }

    fib_sequence // Return the vector containing the first n Fibonacci numbers
}

